//! This module implements cryptographic primitives for verifiable secret sharing (VSS).
//! Each share contains a (Merkle) commitment to the set of all shares generated by the
//! sharing algorithm, so that each share can be individually verified during reconstruction.
//!
//! # Terminology
//!
//! - **Share** ([`VSSShare`]): what is given to one helper. It carries the helper's list of
//!   subshares, the encrypted secret, the Merkle commitment (root) and the Merkle path that
//!   opens this share's leaf to that root. A helper holds exactly one share per split.
//! - **Subshare** ([`Subshare`]): one Shamir `(x, y)` pair, `y = f(x)`. A share carries
//!   one or more subshares; their number is the helper's weight.
//!
//! The threshold `t` counts subshares, not shares: reconstruction needs `t` distinct
//! subshares in total, from any combination of shares. Weights must stay below `t`, so no
//! single share reconstructs on its own.

use super::channel::{decrypt_message, encrypt_message};
use rand::SeedableRng;
use rand::rngs::ChaCha20Rng;
use std::collections::HashSet;
use zeroize::{Zeroize, ZeroizeOnDrop};

mod shamir;
mod utils;

#[allow(non_upper_case_globals)]
const λ_bits: usize = 256;

#[allow(non_upper_case_globals)]
const λ: usize = λ_bits / 8;

const MERKLE_TREE_DEPTH: u32 = 7;

/// The most helpers one split can have: one Merkle leaf per helper. The total number of
/// subshares and the threshold are not capped; only helpers are, by the Merkle tree depth.
const MAX_HELPERS: u64 = 1 << MERKLE_TREE_DEPTH;

/// One subshare: a Shamir `(x, y)` pair with `y = f(x)`, each coordinate a serialized field element.
#[derive(Clone, PartialEq, Eq, Zeroize, ZeroizeOnDrop)]
pub struct Subshare {
    /// The x-coordinate; it identifies the subshare.
    pub x: Vec<u8>,
    /// The y-coordinate, `f(x)`.
    pub y: Vec<u8>,
}

#[derive(Clone, Zeroize, ZeroizeOnDrop)]
pub struct VSSShare {
    /// The subshares this share carries, in the order the Merkle leaf commits to.
    pub subshares: Vec<Subshare>,
    /// AES encryption of the secret message
    pub encrypted_secret: Vec<u8>,
    /// Merkle-root commitment to all shares
    pub commitment: Vec<u8>,
    /// bottom-up Merkle authentication path.
    /// The `bool` denotes `is_left`, while the `Vec<u8>` is the SHA-256 hash.
    pub merkle_path: Vec<(bool, Vec<u8>)>,
}

/// Custom error type for Verifiable Secret Sharing (VSS) operations.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum DerecVSSError {
    #[error("inconsistent ciphertexts")]
    InconsistentCiphertexts,

    #[error("inconsistent commitments")]
    InconsistentCommitments,

    #[error("one or more shares are corrupted")]
    CorruptShares,

    #[error("insufficient shares")]
    InsufficientShares,

    #[error("decryption failed")]
    DecryptionFailure,

    #[error("encryption failed")]
    EncryptionFailure,

    #[error("invalid access structure")]
    InvalidAccessStructure,
}

/// Generates VSS shares for a given secret using Shamir's Secret Sharing scheme,
/// with additional cryptographic commitments for verifiability during reconstruction.
///
/// # Arguments
///
/// * `threshold` - Number of subshares required to reconstruct the secret (`t`). Must satisfy `2 <= threshold`.
/// * `weights` - One entry per share: how many subshares that share carries. Every
///   weight must satisfy `1 <= weight < threshold`, so no single share reconstructs on its
///   own. There can be at most 128 shares (one Merkle leaf each); the weights' sum `n` and
///   the threshold are not capped, so `2 <= threshold <= n`.
/// * `msg` - The secret message to be shared, as a byte slice.
/// * `entropy` - A cryptographically secure random seed of length `λ` (32 bytes).
///
/// # Returns
///
/// One `VSSShare` per entry of `weights`, in the same order, each containing:
///   - `weights[i]` subshares (as bytes),
///   - An AES-encrypted ciphertext of the secret data,
///   - A Merkle root commitment to all shares,
///   - A Merkle authentication path for the share.
///
/// # Details
///
/// - The function derives a pseudo-random AES key and nonce from the message and random seed.
/// - The message is encrypted using AES-256-GCM with the derived key and nonce.
/// - The AES key is split into `n` subshares, handed out to the shares in generation
///   order: the first `weights[0]` subshares to share 0, the next `weights[1]` to share 1, and so on.
/// - A Merkle tree is constructed with one leaf per share, committing to that share's subshares.
/// - Each share includes its Merkle authentication path for individual verification.
///
/// # Errors
///
/// Returns [`DerecVSSError::InvalidAccessStructure`] if `weights` is empty or has more than
/// 128 entries, if a weight is not in `1..threshold`, or if the access structure does not
/// satisfy `2 <= t <= n`.
///
/// Returns [`DerecVSSError::EncryptionFailure`] if AES-GCM encryption of the secret fails.
///
/// # Cost
///
/// Splitting stays cheap at any total `n`, but [`recover`] does not: reconstruction time
/// grows quadratically with the total number of subshares. Measured in release mode on a
/// laptop, one reconstruction attempt takes about 0.2 s at 200 subshares, 5.5 s at 1,000
/// and 87 s at 4,000. This function applies no cap and nothing here signals the cost, so
/// callers should bound `n` themselves.
///
/// # Example
///
/// ```rust
/// use derec_cryptography::vss::{share, recover, VSSShare};
/// let shares = share(3, &[1, 1, 1, 1, 1], b"my secret", &[0u8; 32]).unwrap();
/// assert_eq!(shares.len(), 5);
///
/// // The first helper holds two subshares: with it, one more helper is enough.
/// let weighted = share(3, &[2, 1, 1, 1], b"my secret", &[0u8; 32]).unwrap();
/// let pair = vec![weighted[0].clone(), weighted[3].clone()];
/// assert_eq!(recover(&pair).unwrap(), b"my secret");
/// ```
#[cfg_attr(
    feature = "logging",
    tracing::instrument(
        skip_all,
        fields(threshold, helpers = weights.len(), msg_len = msg.len())
    )
)]
pub fn share(
    threshold: u64,
    weights: &[u64],
    msg: &[u8],
    entropy: &[u8; λ],
) -> Result<Vec<VSSShare>, DerecVSSError> {
    let Some(total_subshares) = total_subshares(threshold, weights) else {
        #[cfg(feature = "logging")]
        tracing::warn!(
            threshold,
            helpers = weights.len(),
            "invalid access structure: weights out of range"
        );
        return Err(DerecVSSError::InvalidAccessStructure);
    };

    //pseudo-random key derivation
    // random_oracle returns [u8; 4*λ], so each λ-byte chunk is statically guaranteed to exist.
    let hash = utils::random_oracle(msg, entropy, &[]);
    let mut k = [0u8; λ];
    let mut nonce = [0u8; λ];
    let mut seed1 = [0u8; λ];
    let mut seed2 = [0u8; λ];
    k.copy_from_slice(&hash[..λ]);
    nonce.copy_from_slice(&hash[λ..2 * λ]);
    seed1.copy_from_slice(&hash[2 * λ..3 * λ]);
    seed2.copy_from_slice(&hash[3 * λ..4 * λ]);

    //AES encrypt the message using the pseudo-random key k
    let c = encrypt_message(msg, &k, &nonce).map_err(|_e| {
        #[cfg(feature = "logging")]
        tracing::warn!(error = %_e, "AES-GCM encryption failed during secret sharing");
        DerecVSSError::EncryptionFailure
    })?;

    // generate shares of the AES key k
    let mut shamir_shares = shamir::share(
        &k,
        threshold,
        total_subshares,
        &mut ChaCha20Rng::from_seed(seed1),
    )
    .into_iter()
    .map(|(x, y)| Subshare { x, y });

    let leaves: Vec<Vec<Subshare>> = weights
        .iter()
        .map(|&weight| shamir_shares.by_ref().take(weight as usize).collect())
        .collect();

    let merkle_tree = utils::build_merkle_tree(
        &leaves,
        MERKLE_TREE_DEPTH,
        &mut ChaCha20Rng::from_seed(seed2),
    );
    let merkle_proofs =
        utils::extract_merkle_proofs(&merkle_tree, MERKLE_TREE_DEPTH, leaves.len() as u64);

    let output: Vec<VSSShare> = leaves
        .into_iter()
        .zip(merkle_proofs)
        .map(|(subshares, merkle_path)| VSSShare {
            subshares,
            encrypted_secret: c.clone(),
            commitment: merkle_tree[0].clone(),
            merkle_path,
        })
        .collect();
    #[cfg(feature = "logging")]
    tracing::info!(shares_count = output.len(), "secret split into VSS shares");

    Ok(output)
}

/// The number of subshares `weights` hands out, or `None` when the access structure is
/// invalid: no shares, more than [`MAX_HELPERS`] shares, a weight outside `1..threshold`, a
/// total below `threshold`, or `threshold < 2`.
fn total_subshares(threshold: u64, weights: &[u64]) -> Option<u64> {
    if weights.is_empty() || weights.len() as u64 > MAX_HELPERS {
        return None;
    }
    let mut total: u64 = 0;
    for &weight in weights {
        if weight == 0 || weight >= threshold {
            return None;
        }
        total = total.checked_add(weight)?;
    }
    (threshold <= total).then_some(total)
}

/// Whether `subshares` can be a share's subshare list: at least one subshare and no x-coordinate
/// twice.
fn subshares_are_well_formed(subshares: &[Subshare]) -> bool {
    let mut seen = HashSet::with_capacity(subshares.len());
    !subshares.is_empty() && subshares.iter().all(|p| seen.insert(p.x.as_slice()))
}

/// Verifies that a single VSS share is consistent with its Merkle commitment.
///
/// Re-derives the Merkle root by hashing `share.subshares` as a leaf node
/// and then walking up `share.merkle_path`. The computed root is compared to
/// `share.commitment`. `share.encrypted_secret` is not examined.
///
/// The root is the one the share carries, so a share that passes is intact,
/// not necessarily valid: whether it belongs to a secret is only known by
/// comparing it with other shares, which [`recover`] does.
///
/// # Arguments
///
/// * `share` - The [`VSSShare`] to verify.
///
/// # Returns
///
/// `true` if the recomputed root equals `share.commitment`, `false` otherwise,
/// including when `share.merkle_path` does not span the full tree depth, and when
/// `share.subshares` is empty or repeats an x-coordinate.
///
/// # Example
///
/// ```rust
/// use derec_cryptography::vss::{share, verify};
///
/// let shares = share(2, &[1, 1, 1], b"my secret", &[0u8; 32]).unwrap();
/// assert!(verify(&shares[0]));
/// ```
#[cfg_attr(feature = "logging", tracing::instrument(skip_all))]
pub fn verify(share: &VSSShare) -> bool {
    if share.merkle_path.len() != MERKLE_TREE_DEPTH as usize
        || !subshares_are_well_formed(&share.subshares)
    {
        return false;
    }

    let mut on_path_hash = utils::leaf_hash_pub(&share.subshares);

    for (is_left, node_hash) in &share.merkle_path {
        on_path_hash = if *is_left {
            utils::intermediate_hash_pub(node_hash, &on_path_hash)
        } else {
            utils::intermediate_hash_pub(&on_path_hash, node_hash)
        };
    }

    let result = on_path_hash == share.commitment;

    #[cfg(feature = "logging")]
    tracing::debug!(verified = result, "Merkle proof checked");

    result
}

/// Recovers the secret from a set of VSS shares.
///
/// Reconstruction proceeds in three stages:
///
/// 1. **Integrity check** — verifies that all shares are consistent:
///    - all `commitment` fields are equal (same Merkle root)
///    - all `encrypted_secret` fields are equal (same ciphertext)
///    - each share's Merkle authentication path opens correctly to the common root
/// 2. **Shamir interpolation** — reconstructs the AES key `k` from the subshares of
///    every share together, using polynomial interpolation over the underlying field.
/// 3. **Decryption** — decrypts `encrypted_secret` with the recovered key `k`
///    to obtain the original secret bytes.
///
/// # Arguments
///
/// * `shares` - A non-empty collection of [`VSSShare`] values. Together they must carry
///   at least `t` subshares (the threshold used during [`share`]) for reconstruction to
///   succeed. Fewer than `t` valid subshares cause decryption to fail.
///
/// # Returns
///
/// `Ok(Vec<u8>)` containing the recovered secret on success.
///
/// # Errors
///
/// - [`DerecVSSError::InconsistentCommitments`] — shares carry different Merkle roots
/// - [`DerecVSSError::InconsistentCiphertexts`] — shares carry different ciphertexts
/// - [`DerecVSSError::CorruptShares`] — one or more Merkle proofs fail to verify,
///   a share's subshare list is malformed (see [`verify`]), a coordinate is not a valid
///   field element, or the same x-coordinate appears twice across the shares
/// - [`DerecVSSError::InsufficientShares`] — `shares` is empty, or Shamir
///   interpolation produced a key that fails to decrypt the ciphertext (fewer
///   than `t` valid subshares were supplied)
///
/// # Cost
///
/// Reconstruction time grows quadratically with the total number of subshares across
/// `shares`. Measured in release mode on a laptop, one attempt takes about 0.2 s at 200
/// subshares, 5.5 s at 1,000 and 87 s at 4,000. No cap is applied here: the subshares a
/// secret was split into are all a recovering caller has, and refusing them could leave
/// the secret unrecoverable. The total is bounded where the secret is split (see [`share`]).
///
/// # Example
///
/// ```rust
/// use derec_cryptography::vss::{share, recover};
///
/// let shares = share(3, &[1, 1, 1, 1, 1], b"my secret", &[0u8; 32]).unwrap();
/// let secret = recover(&shares[..3].to_vec()).unwrap();
/// assert_eq!(secret, b"my secret");
/// ```
#[cfg_attr(
    feature = "logging",
    tracing::instrument(skip_all, fields(shares_count = shares.len()))
)]
pub fn recover(shares: &Vec<VSSShare>) -> Result<Vec<u8>, DerecVSSError> {
    if shares.is_empty() {
        return Err(DerecVSSError::InsufficientShares);
    }

    // Stage 1: verify consistency across shares and validate each Merkle proof.
    let detected_error = utils::detect_error(shares);
    if let Some(err) = detected_error {
        #[cfg(feature = "logging")]
        tracing::warn!(error = %err, "share consistency check failed");
        return Err(err);
    }

    // Stage 2: reconstruct the AES key via Shamir polynomial interpolation.
    let shamir_shares = shares
        .iter()
        .flat_map(|s| s.subshares.iter().map(|p| (p.x.clone(), p.y.clone())))
        .collect();
    let k = shamir::recover(shamir_shares).ok_or(DerecVSSError::CorruptShares)?;

    // Stage 3: decrypt the ciphertext with the recovered key.
    // A decryption failure here means insufficient or wrong shares were provided.
    let c = shares[0].encrypted_secret.clone();
    let secret = decrypt_message(&c, &k).map_err(|_e| {
        #[cfg(feature = "logging")]
        tracing::warn!("decryption failed; insufficient or incorrect shares");
        DerecVSSError::InsufficientShares
    })?;

    #[cfg(feature = "logging")]
    tracing::info!(
        secret_len = secret.len(),
        "secret reconstructed from shares"
    );

    Ok(secret)
}

#[cfg(test)]
mod tests {
    use super::*;

    const ENTROPY: &[u8; λ] = &[0u8; λ];

    #[test]
    fn test_share_rejects_threshold_below_2() {
        let Err(err) = share(1, &[1; 5], b"secret", ENTROPY) else {
            panic!("threshold < 2 should be rejected");
        };
        assert!(matches!(err, DerecVSSError::InvalidAccessStructure));
    }

    #[test]
    fn test_share_rejects_threshold_greater_than_n() {
        let Err(err) = share(5, &[1; 3], b"secret", ENTROPY) else {
            panic!("t > n should be rejected");
        };
        assert!(matches!(err, DerecVSSError::InvalidAccessStructure));
    }

    #[test]
    fn test_share_rejects_n_exceeding_max() {
        // max is 2^MERKLE_TREE_DEPTH = 128
        let Err(err) = share(2, &[1; 129], b"secret", ENTROPY) else {
            panic!("n > 128 should be rejected");
        };
        assert!(matches!(err, DerecVSSError::InvalidAccessStructure));
    }

    #[test]
    fn test_share_accepts_boundary_values() {
        // t == n == 2  (minimum valid)
        let shares = share(2, &[1; 2], b"secret", ENTROPY).expect("(2,2) should be valid");
        assert_eq!(shares.len(), 2);

        // n == 128  (maximum valid)
        let shares = share(2, &[1; 128], b"secret", ENTROPY).expect("(2,128) should be valid");
        assert_eq!(shares.len(), 128);
    }

    #[test]
    fn test_share_produces_correct_number_of_shares() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        assert_eq!(shares.len(), 5);
    }

    #[test]
    fn test_share_all_shares_carry_same_commitment_and_ciphertext() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let first_commitment = &shares[0].commitment;
        let first_ciphertext = &shares[0].encrypted_secret;
        for s in &shares {
            assert_eq!(&s.commitment, first_commitment, "commitments must match");
            assert_eq!(
                &s.encrypted_secret, first_ciphertext,
                "ciphertexts must match"
            );
        }
    }

    #[test]
    fn test_share_is_deterministic() {
        let shares_a = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let shares_b = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        for (a, b) in shares_a.iter().zip(shares_b.iter()) {
            assert!(a.subshares == b.subshares);
            assert_eq!(a.commitment, b.commitment);
            assert_eq!(a.encrypted_secret, b.encrypted_secret);
        }
    }

    #[test]
    fn test_verify_accepts_all_valid_shares() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        for s in &shares {
            assert!(verify(s), "every generated share should verify");
        }
    }

    #[test]
    fn test_verify_rejects_tampered_x_coordinate() {
        let mut shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        shares[0].subshares[0].x[0] ^= 0xFF;
        assert!(!verify(&shares[0]), "tampered x should fail Merkle proof");
    }

    #[test]
    fn test_verify_rejects_tampered_y_coordinate() {
        let mut shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        shares[0].subshares[0].y[0] ^= 0xFF;
        assert!(!verify(&shares[0]), "tampered y should fail Merkle proof");
    }

    // An internal node is the hash of its two children, so its children can be
    // passed off as a share's (x, y) with the shorter proof from that node to the root.
    fn internal_node_as_share(genuine: &VSSShare) -> VSSShare {
        let (sibling_is_left, sibling) = &genuine.merkle_path[0];
        let leaf = utils::leaf_hash_pub(&genuine.subshares);
        let (left, right) = if *sibling_is_left {
            (sibling.clone(), leaf)
        } else {
            (leaf, sibling.clone())
        };
        VSSShare {
            subshares: vec![Subshare { x: left, y: right }],
            encrypted_secret: genuine.encrypted_secret.clone(),
            commitment: genuine.commitment.clone(),
            merkle_path: genuine.merkle_path[1..].to_vec(),
        }
    }

    #[test]
    fn test_verify_rejects_an_internal_node_presented_as_a_leaf() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let forged = internal_node_as_share(&shares[0]);

        assert!(
            !verify(&forged),
            "an internal node must not verify as a share"
        );
    }

    #[test]
    fn test_internal_node_presented_as_a_leaf_does_not_open_to_the_root() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let forged = internal_node_as_share(&shares[0]);

        // Walk the forged proof without the depth check, so only the
        // leaf/internal-node domain separation stands between it and the root.
        let mut on_path_hash = utils::leaf_hash_pub(&forged.subshares);
        for (is_left, node_hash) in &forged.merkle_path {
            on_path_hash = if *is_left {
                utils::intermediate_hash_pub(node_hash, &on_path_hash)
            } else {
                utils::intermediate_hash_pub(&on_path_hash, node_hash)
            };
        }

        assert_ne!(on_path_hash, forged.commitment);
    }

    #[test]
    fn test_verify_rejects_a_proof_that_is_not_the_tree_depth() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();

        let mut short = shares[0].clone();
        short.merkle_path.pop();
        assert!(!verify(&short), "a truncated proof must not verify");

        let mut long = shares[0].clone();
        long.merkle_path.push((false, vec![0u8; 32]));
        assert!(!verify(&long), "an extended proof must not verify");
    }

    #[test]
    fn test_recover_rejects_an_internal_node_presented_as_a_leaf() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let forged = vec![
            internal_node_as_share(&shares[0]),
            shares[2].clone(),
            shares[3].clone(),
        ];

        let err = recover(&forged).expect_err("an internal node must not pass as a share");
        assert!(matches!(err, DerecVSSError::CorruptShares));
    }

    #[test]
    fn test_recover_exact_threshold() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let secret = recover(&shares[..3].to_vec()).unwrap();
        assert_eq!(secret, b"my secret");
    }

    #[test]
    fn test_recover_all_shares() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let secret = recover(&shares).unwrap();
        assert_eq!(secret, b"my secret");
    }

    #[test]
    fn test_recover_fails_below_threshold() {
        let shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        // Only 2 shares with threshold 3 — reconstruction produces the wrong key.
        let err = recover(&shares[..2].to_vec()).expect_err("recovery below threshold should fail");
        assert!(matches!(err, DerecVSSError::InsufficientShares));
    }

    #[test]
    fn test_recover_detects_inconsistent_commitments() {
        let mut shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        // Replace share[1]'s commitment with one from a different run.
        let other = share(3, &[1; 5], b"other secret", ENTROPY).unwrap();
        shares[1].commitment = other[1].commitment.clone();

        let err = recover(&shares[..3].to_vec())
            .expect_err("inconsistent commitments should be detected");
        assert!(matches!(err, DerecVSSError::InconsistentCommitments));
    }

    #[test]
    fn test_recover_detects_inconsistent_ciphertexts() {
        let mut shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        let other = share(3, &[1; 5], b"other secret", ENTROPY).unwrap();
        shares[1].encrypted_secret = other[1].encrypted_secret.clone();

        let err = recover(&shares[..3].to_vec())
            .expect_err("inconsistent ciphertexts should be detected");
        assert!(matches!(err, DerecVSSError::InconsistentCiphertexts));
    }

    #[test]
    fn test_recover_detects_corrupt_share() {
        let mut shares = share(3, &[1; 5], b"my secret", ENTROPY).unwrap();
        shares[0].subshares[0].y[0] ^= 0xFF;

        let err = recover(&shares[..3].to_vec()).expect_err("corrupt share should be detected");
        assert!(matches!(err, DerecVSSError::CorruptShares));
    }

    #[test]
    fn test_recover_rejects_empty_input_without_panicking() {
        let err = recover(&Vec::new()).expect_err("no shares cannot recover");
        assert!(matches!(err, DerecVSSError::InsufficientShares));
    }

    #[test]
    fn test_recover_rejects_a_repeated_share_without_panicking() {
        let shares = share(2, &[1; 3], b"my secret", ENTROPY).unwrap();
        let repeated = vec![shares[0].clone(), shares[0].clone()];
        let err = recover(&repeated).expect_err("one subshare twice cannot interpolate");
        assert!(matches!(err, DerecVSSError::CorruptShares));
    }

    #[test]
    fn test_recover_rejects_a_proven_coordinate_that_is_not_a_field_element() {
        let mut shares = share(2, &[1; 2], b"my secret", ENTROPY).unwrap();
        shares[0].subshares[0].y = vec![0xFF; shares[0].subshares[0].y.len()];
        let tree = utils::build_merkle_tree(
            &leaves_of(&shares),
            MERKLE_TREE_DEPTH,
            &mut crate::random::os_rng(),
        );
        let proofs = utils::extract_merkle_proofs(&tree, MERKLE_TREE_DEPTH, 2);
        for (s, proof) in shares.iter_mut().zip(proofs) {
            s.commitment = tree[0].clone();
            s.merkle_path = proof;
        }

        let err = recover(&shares).expect_err("an undecodable coordinate cannot interpolate");
        assert!(matches!(err, DerecVSSError::CorruptShares));
    }

    #[test]
    fn test_encryption_failure_error_message() {
        let err = DerecVSSError::EncryptionFailure;
        assert_eq!(err.to_string(), "encryption failed");
    }

    const WEIGHTS: &[u64] = &[2, 1, 1, 1];

    fn weighted() -> Vec<VSSShare> {
        share(3, WEIGHTS, b"my secret", ENTROPY).unwrap()
    }

    #[test]
    fn test_weighted_share_gives_each_helper_its_weight() {
        let shares = weighted();
        let counts: Vec<usize> = shares.iter().map(|s| s.subshares.len()).collect();
        assert_eq!(counts, vec![2, 1, 1, 1]);
        for s in &shares {
            assert!(verify(s), "every weighted share should verify");
        }
    }

    #[test]
    fn test_weighted_heavy_helper_plus_one_recovers() {
        let shares = weighted();
        for i in 1..4 {
            let pair = vec![shares[0].clone(), shares[i].clone()];
            assert_eq!(recover(&pair).unwrap(), b"my secret");
        }
    }

    #[test]
    fn test_weighted_three_unit_helpers_recover() {
        let shares = weighted();
        assert_eq!(recover(&shares[1..].to_vec()).unwrap(), b"my secret");
    }

    #[test]
    fn test_weighted_heavy_helper_alone_or_two_unit_helpers_fail() {
        let shares = weighted();
        let alone = recover(&vec![shares[0].clone()]).expect_err("2 subshares < t = 3");
        assert!(matches!(alone, DerecVSSError::InsufficientShares));
        for (a, b) in [(1, 2), (1, 3), (2, 3)] {
            let two = vec![shares[a].clone(), shares[b].clone()];
            let err = recover(&two).expect_err("2 subshares < t = 3");
            assert!(matches!(err, DerecVSSError::InsufficientShares));
        }
    }

    #[test]
    fn test_share_rejects_bad_weights() {
        let cases: &[(u64, &[u64])] = &[
            (3, &[]),
            (3, &[0, 1, 1]),
            (3, &[3, 1, 1]),
            (2, &[1; 129]),
            (3, &[u64::MAX, 1]),
            (u64::MAX, &[u64::MAX - 1, 2]),
            (5, &[1, 1, 1]),
            (1, &[1, 1]),
        ];
        for (t, weights) in cases {
            let Err(err) = share(*t, weights, b"secret", ENTROPY) else {
                panic!("t = {t}, weights = {weights:?} should be rejected");
            };
            assert!(matches!(err, DerecVSSError::InvalidAccessStructure));
        }
    }

    #[test]
    fn test_share_is_deterministic_with_weights() {
        let a = share(3, &[2, 1, 1], b"my secret", ENTROPY).unwrap();
        let b = share(3, &[2, 1, 1], b"my secret", ENTROPY).unwrap();
        for (a, b) in a.iter().zip(b.iter()) {
            assert!(a.subshares == b.subshares);
            assert_eq!(a.commitment, b.commitment);
            assert_eq!(a.encrypted_secret, b.encrypted_secret);
        }
    }

    /// Re-commits `leaves` under a fresh Merkle tree, so every share's proof opens to the
    /// root and only the subshare-list checks stand between a malformed share and `verify`.
    fn commit(leaves: Vec<Vec<Subshare>>, encrypted_secret: &[u8]) -> Vec<VSSShare> {
        let tree =
            utils::build_merkle_tree(&leaves, MERKLE_TREE_DEPTH, &mut crate::random::os_rng());
        let proofs = utils::extract_merkle_proofs(&tree, MERKLE_TREE_DEPTH, leaves.len() as u64);
        leaves
            .into_iter()
            .zip(proofs)
            .map(|(subshares, merkle_path)| VSSShare {
                subshares,
                encrypted_secret: encrypted_secret.to_vec(),
                commitment: tree[0].clone(),
                merkle_path,
            })
            .collect()
    }

    fn leaves_of(shares: &[VSSShare]) -> Vec<Vec<Subshare>> {
        shares.iter().map(|s| s.subshares.clone()).collect()
    }

    #[test]
    fn test_verify_rejects_empty_subshares() {
        let shares = weighted();
        let mut leaves = leaves_of(&shares);
        leaves[1].clear();
        let committed = commit(leaves, &shares[0].encrypted_secret);
        assert!(!verify(&committed[1]), "a share must carry a subshare");
    }

    #[test]
    fn test_verify_rejects_duplicate_x_within_a_share() {
        let shares = weighted();
        let mut leaves = leaves_of(&shares);
        leaves[0][1] = leaves[0][0].clone();
        let committed = commit(leaves, &shares[0].encrypted_secret);
        assert!(
            !verify(&committed[0]),
            "a share must not repeat an x-coordinate"
        );
    }

    #[test]
    fn test_verify_rejects_reordered_subshares() {
        let mut s = weighted().remove(0);
        s.subshares.swap(0, 1);
        assert!(!verify(&s), "subshare order is committed by the leaf");
    }

    #[test]
    fn test_verify_rejects_removed_subshare() {
        let mut s = weighted().remove(0);
        s.subshares.pop();
        assert!(!verify(&s));
    }

    #[test]
    fn test_verify_rejects_added_subshare() {
        let shares = weighted();
        let mut s = shares[1].clone();
        s.subshares.push(shares[2].subshares[0].clone());
        assert!(!verify(&s));
    }

    #[test]
    fn test_verify_accepts_a_share_of_200_subshares() {
        // 200 subshares need not come from one split: build the list from two
        // independent splits of the same secret and commit it as one share.
        // Distinct entropy keeps the two splits' x-coordinates apart.
        const OTHER_ENTROPY: &[u8; λ] = &[1u8; λ];
        let a = share(2, &[1; 128], b"my secret", ENTROPY).unwrap();
        let b = share(2, &[1; 72], b"my secret", OTHER_ENTROPY).unwrap();
        let subshares: Vec<Subshare> = a
            .iter()
            .chain(b.iter())
            .map(|s| s.subshares[0].clone())
            .collect();
        assert_eq!(subshares.len(), 200);
        let big = commit(vec![subshares], &a[0].encrypted_secret).remove(0);
        assert!(verify(&big), "a share of 200 subshares verifies");
    }

    #[test]
    fn test_threshold_above_128_with_two_helpers_recovers() {
        let shares = share(150, &[100, 100], b"s", ENTROPY).unwrap();
        assert_eq!(shares.len(), 2);
        assert_eq!(recover(&shares).unwrap(), b"s");

        let err = recover(&vec![shares[0].clone()])
            .expect_err("one helper's 100 subshares is below the threshold of 150");
        assert!(matches!(err, DerecVSSError::InsufficientShares));
    }

    #[test]
    fn test_recover_rejects_a_committed_share_with_malformed_subshares() {
        let shares = weighted();
        let mut leaves = leaves_of(&shares);
        leaves[0][1] = leaves[0][0].clone();
        let committed = commit(leaves, &shares[0].encrypted_secret);
        let err = recover(&committed).expect_err("malformed subshare list");
        assert!(matches!(err, DerecVSSError::CorruptShares));
    }

    #[test]
    fn test_recover_rejects_same_x_in_two_shares() {
        let shares = weighted();
        let mut leaves = leaves_of(&shares);
        leaves[1] = vec![shares[0].subshares[0].clone()];
        let rebuilt = commit(leaves, &shares[0].encrypted_secret);
        for s in &rebuilt {
            assert!(verify(s), "each share is individually well formed");
        }

        let err = recover(&rebuilt[..3].to_vec()).expect_err("x repeated across shares");
        assert!(matches!(err, DerecVSSError::CorruptShares));
    }
}
